SELECT * FROM (SELECT Description, Startstamp, Stopstamp, IF(Time_Stop = 0, TIMEDIFF(NOW(),FROM_UNIXTIME(Time_Start)), SEC_TO_TIME(Time_Stop - Time_Start)) AS Duration, CASE Severity WHEN 0 THEN 'INVALID' WHEN 1 THEN 'INFORMATION ONLY' WHEN 2 THEN 'GOOD MSG' WHEN 3 THEN 'WARNING' WHEN 4 THEN 'FULL WARNING' WHEN 5 THEN 'ERROR SYSTEM STILL RUNNING' WHEN 6 THEN 'HARD ERROR  SYSTEM STOPS' WHEN 7 THEN 'JAM ERROR  SYSTEM STOPS' WHEN 8 THEN 'FULLJAM' ELSE 'UNKNOWN' END AS Severity, LinkPart FROM Error_Log ORDER BY Startstamp DESC) AS ErrorStatusLog

